CREATE TABLE IF NOT EXISTS community_branding(id TINYINT UNSIGNED PRIMARY KEY,file_data MEDIUMBLOB NULL,mime_type VARCHAR(80) NULL,sha256 CHAR(64) NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
ALTER TABLE applications ADD COLUMN IF NOT EXISTS submission_key VARCHAR(64) NULL;
CREATE UNIQUE INDEX IF NOT EXISTS application_submission_key ON applications(user_id,submission_key);
INSERT IGNORE INTO community_branding(id) VALUES(1);
INSERT IGNORE INTO site_settings(setting_key,setting_value) VALUES('tablet_applications_enabled','1'),('tablet_dispatch_enabled','1'),('tablet_cad_enabled','1'),('tablet_hud_enabled','1'),('tablet_panic_enabled','1');
ALTER TABLE fivem_active_units ADD COLUMN IF NOT EXISTS position_x DOUBLE NULL;
ALTER TABLE fivem_active_units ADD COLUMN IF NOT EXISTS position_y DOUBLE NULL;
ALTER TABLE fivem_active_units ADD COLUMN IF NOT EXISTS position_z DOUBLE NULL;
CREATE TABLE IF NOT EXISTS fivem_calls(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,server_id BIGINT UNSIGNED NOT NULL,title VARCHAR(160) NOT NULL,description TEXT NULL,location VARCHAR(255) NULL,priority ENUM('P1','P2','P3') NOT NULL DEFAULT 'P3',status ENUM('open','closed') NOT NULL DEFAULT 'open',position_x DOUBLE NULL,position_y DOUBLE NULL,created_by BIGINT UNSIGNED NULL,panic_user_id BIGINT UNSIGNED NULL,panic_open TINYINT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,closed_at DATETIME NULL,UNIQUE KEY open_panic(server_id,panic_user_id,panic_open),INDEX(server_id,status),FOREIGN KEY(server_id) REFERENCES fivem_servers(id),FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS fivem_call_units(call_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,status ENUM('assigned','enroute','on_scene','cleared') NOT NULL DEFAULT 'assigned',updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(call_id,user_id),FOREIGN KEY(call_id) REFERENCES fivem_calls(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS fivem_call_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,call_id BIGINT UNSIGNED NOT NULL,actor_id BIGINT UNSIGNED NULL,event VARCHAR(255) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(call_id) REFERENCES fivem_calls(id) ON DELETE CASCADE,FOREIGN KEY(actor_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS cad_people(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,dob DATE NULL,license_status ENUM('valid','suspended','revoked','unknown') NOT NULL DEFAULT 'unknown',notes TEXT NULL,created_by BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(name));
CREATE TABLE IF NOT EXISTS cad_vehicles(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,plate VARCHAR(16) NOT NULL UNIQUE,model VARCHAR(120) NOT NULL,color VARCHAR(80) NULL,owner_id BIGINT UNSIGNED NULL,notes TEXT NULL,created_by BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(owner_id) REFERENCES cad_people(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS cad_bolos(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(160) NOT NULL,description TEXT NOT NULL,person_id BIGINT UNSIGNED NULL,vehicle_id BIGINT UNSIGNED NULL,status ENUM('active','closed') NOT NULL DEFAULT 'active',created_by BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(person_id) REFERENCES cad_people(id) ON DELETE SET NULL,FOREIGN KEY(vehicle_id) REFERENCES cad_vehicles(id) ON DELETE SET NULL);
